import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url)
        response.raise_for_status()
        with open(zip_path, 'wb') as f:
            f.write(response.content)
    except requests.RequestException as e:
        raise ConnectionError(f"Network error downloading the file: {e}")
    except IOError as e:
        raise IOError(f"File error saving the downloaded content: {e}")
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            extracted_files = []
            for member in zip_ref.namelist():
                zip_ref.extract(member, ZIP_DIR)
                extracted_files.append(member)
        return ("Downloaded and extracted successfully.", extracted_files)
    except (zipfile.BadZipFile, OSError) as e:
        return (f"Error extracting the ZIP file: {e}", [])

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if not detected.get('encoding'):
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    decoded = content.decode(from_encoding)
    reencoded = decoded.encode(to_encoding)
    return json.loads(reencoded)

import requests
import logging

def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url)
        response.raise_for_status()
        repo_data = response.json()
        if isinstance(repo_data, dict) and repo_data.get('open_issues_count', 0) > 100:
            logging.warning(f"Repository has many open issues: {repo_data.get('open_issues_count')}")
        return repo_data
    except requests.exceptions.HTTPError as e:
