HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("URL and parameters must be provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve data from {url}: {e}")

    if not data:
        raise Exception("No data retrieved from the API.")

    try:
        df = pd.DataFrame(data)
        numeric_df = df.select_dtypes(include=['number'])
        if numeric_df.empty:
            raise Exception("No numeric columns available for correlation.")
        corr_matrix = numeric_df.corr()
    except Exception as e:
        raise Exception(f"Error processing data into DataFrame or correlation: {e}")

    try:
        _, ax = plt.subplots()
        sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', ax=ax)
        ax.set_title('Correlation Heatmap')
    except Exception as e:
        raise Exception(f"Error generating heatmap: {e}")

    return (df, ax)

